<template>
  <section class="results-workspace"><header><div><span class="eyebrow">{{ app.basinName }}</span><h1>计算成果</h1></div><button class="btn" :disabled="loading" @click="refresh">刷新</button></header>
    <div class="results-tools"><div class="result-tabs"><button class="btn" :class="{primary:tab==='saved'}" @click="tab='saved'">我的成果</button><button class="btn" :class="{primary:tab==='recent'}" @click="tab='recent'">最近计算</button></div><input v-model="search" type="search" class="input" aria-label="查找成果" placeholder="查找成果、参数或计算日期" /><select v-model="type" class="input" aria-label="成果计算类型"><option value="">全部计算</option><option v-for="(label,key) in operationLabels" :key="key" :value="key">{{ label }}</option></select></div>
    <p v-if="error" class="error" role="alert">{{ error }}</p>
    <div class="results-layout"><section class="panel results-list"><div class="list-count">{{ filtered.length }} 次计算</div><button v-for="row in paged" :key="row.id" class="result-row" :class="{selected:selectedId===row.id}" @click="inspect(row)"><div><b>{{ row.name }}</b><span>{{ operationLabels[row.type] || '水文计算' }} · {{ statusLabels[row.status] || row.status }}<template v-if="row.processCount > 1"> · {{ row.processCount }} 个过程</template></span><span>{{ dateLabel(row.createdAt) }}<template v-if="row.parameterName"> · {{ row.parameterName }}</template></span></div><i>→</i></button><p v-if="!paged.length" class="empty">{{ loading ? '正在读取计算记录…' : tab === 'saved' ? '暂无命名成果。完成计算后点击“保存成果”。' : '暂无计算记录' }}</p><footer v-if="filtered.length"><span>{{ page }} / {{ pages }} 页</span><button class="btn" :disabled="page<=1" @click="page--">上一页</button><button class="btn" :disabled="page>=pages" @click="page++">下一页</button></footer></section>
      <section class="result-detail" v-if="selected"><div class="panel detail-heading"><h2>{{ selected.name }}</h2><p>{{ operationLabels[selected.type] || '水文计算' }} · {{ dateLabel(selected.createdAt) }}</p><p v-if="selected.error" class="error">{{ selected.error }}</p><p v-if="loadingResult">正在读取成果过程…</p><DailyOperationProgress v-if="activeStatus" :operation="status" @cancel="cancel" /><template v-if="result"><ResultSaveBar :result-id="selectedId" :suggestion="selected.suggestedName" @saved="renamed" /><div class="detail-actions"><button class="btn" :disabled="runningAction" @click="rerun">按原条件复算</button><button class="btn" @click="saveParameter">另存参数</button><button class="btn" @click="openConditions">打开计算条件</button><button class="btn" @click="saveAsScheme">另存为方案</button></div><p v-if="actionMessage" role="status">{{ actionMessage }}</p></template></div>
        <DailyResultPanel v-if="result" :operation="displayStatus" :result="result" :task-id="result.primaryTaskId || result.taskId || selectedId" :comparison-options="comparisons" :title="selected.name" hide-save-bar />
        <details v-if="result?.timings" class="panel timing-details"><summary>计算耗时</summary><p v-for="(value,key) in result.timings" :key="key">{{ timingLabels[key] || key }}：{{ value }} 秒</p></details>
      </section><section v-else class="panel result-placeholder">选择一份成果查看过程、比较计算或查询断面流量。</section></div>
  </section>
</template>
<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessageBox } from 'element-plus'
import { useAppStore } from '@/stores/app'
import { modelApi } from '@/services/modelBackendService'
import { schemeDefinition } from '@/services/modelSchemeService'
import DailyResultPanel from '@/components/model/DailyResultPanel.vue'
import DailyOperationProgress from '@/components/model/DailyOperationProgress.vue'
import ResultSaveBar from '@/components/model/ResultSaveBar.vue'
const app = useAppStore(), route = useRoute(), router = useRouter()
const rows = ref([]), selectedId = ref(''), selected = ref(null), result = ref(null), status = ref(null), tab = ref('saved'), search = ref(''), type = ref(''), page = ref(1), loading = ref(false), loadingResult = ref(false), error = ref(''), runningAction = ref(false), actionMessage = ref('')
const operationLabels = { calibration:'参数率定',manualTrial:'人工试调',eventSimulation:'洪水模拟',continuousSimulation:'连续模拟',simulation:'洪水模拟',continuousCalibration:'连续率定',eventCalibration:'场次率定',continuation:'继续模拟',rerun:'原条件复算',hindcast:'历史回算',rollingHindcast:'滚动回算',forecast:'洪水预报',stateInitialization:'状态计算',stateContinuation:'继续模拟' }
const statusLabels = { completed:'已完成',archived:'已完成',running:'计算中',queued:'排队中',cancelling:'正在停止',cancelled:'已停止',failed:'未完成' }
const timingLabels = { operationSeconds:'总耗时',queueSeconds:'排队',inputPreparationSeconds:'输入准备',preparationSeconds:'资料读取与检查',compilationSeconds:'编译与缓存加载',searchSeconds:'参数搜索',finalEvaluationSeconds:'最终评价',stateSavingSeconds:'状态生成与保存',simulationSeconds:'模型计算',statePersistenceSeconds:'状态文件保存',warmupSeconds:'预热产流',loadingSeconds:'读取冻结资料',runoffFirstCallSeconds:'首次产流调用（包含编译或缓存加载，与预热或产流耗时重叠）',runoffSeconds:'评价期产流',routingSeconds:'全程汇流',checkpointSeconds:'末状态保存' }
const filtered = computed(() => rows.value.filter(row => (tab.value === 'saved' ? row.saved : true) && (!type.value || row.type === type.value) && `${row.name} ${row.parameterName || ''} ${row.createdAt || ''}`.includes(search.value.trim())))
const pages = computed(() => Math.max(1,Math.ceil(filtered.value.length/10)))
const paged = computed(() => filtered.value.slice((page.value-1)*10,page.value*10))
watch([tab,search,type],()=>{page.value=1})
watch(pages,value=>{page.value=Math.min(page.value,value)})
const activeStatus = computed(()=>['queued','running','cancelling'].includes(status.value?.status))
const displayStatus = computed(()=>({...status.value, name:selected.value?.name, operationId:selectedId.value.startsWith('OP-')?selectedId.value:undefined, taskId:selectedId.value, canonicalResultId:selectedId.value}))
const comparisons = computed(()=>rows.value.filter(row=>['completed','archived'].includes(row.status)).map(row=>({id:row.id,name:row.name})))
const dateLabel = value => value ? new Date(value).toLocaleString('zh-CN',{hour12:false}) : '日期未登记'
let sequence=0,poll,disposed=false
async function refresh(){loading.value=true;error.value='';try{const payload=await modelApi('result-catalog',{timeoutMs:60000});if(disposed)return;rows.value=(payload.results||[]).filter(row=>!row.contextKey||row.contextKey===app.contextKey);const requested=route.query.result||route.query.operation||route.query.task;const wanted=requested&&rows.value.find(row=>row.id===requested||row.sourceTaskIds?.includes(requested));if(wanted&&selectedId.value!==wanted.id){if(!wanted.saved)tab.value='recent';await inspect(wanted)}else if(selected.value){selected.value=rows.value.find(row=>row.id===selectedId.value)||selected.value}}catch(failure){error.value=failure.message}finally{loading.value=false}}
async function inspect(row){const token=++sequence;clearTimeout(poll);selected.value=row;selectedId.value=row.id;result.value=null;status.value=null;loadingResult.value=true;error.value='';actionMessage.value='';try{if(['completed','archived'].includes(row.status)){const payload=await modelApi('results/'+row.id,{timeoutMs:60000});if(token!==sequence||disposed)return;result.value=payload.result;status.value=payload.status}else{status.value=await modelApi((row.id.startsWith('OP-')?'operations/':'tasks/')+row.id);if(token!==sequence||disposed)return;if(['queued','running','cancelling'].includes(status.value.status))poll=setTimeout(async()=>{await refresh();const latest=rows.value.find(item=>item.id===row.id);if(latest)inspect(latest)},1500)}}catch(failure){if(token===sequence)error.value=failure.message}finally{if(token===sequence)loadingResult.value=false}}
async function renamed(metadata){selected.value={...selected.value,name:metadata.name,saved:true,metadata};rows.value=rows.value.map(row=>row.id===selectedId.value?selected.value:row);tab.value='saved'}
async function cancel(){try{await modelApi((selectedId.value.startsWith('OP-')?'operations/':'tasks/')+selectedId.value+'/cancel',{method:'POST',body:{}});await refresh()}catch(failure){error.value=failure.message}}
async function rerun(){runningAction.value=true;error.value='';try{const task=await modelApi('operations',{method:'POST',body:{operation:'rerun',sourceTaskId:selectedId.value}});tab.value='recent';await refresh();const row=rows.value.find(item=>item.id===task.taskId);if(row)await inspect(row)}catch(failure){error.value=failure.message}finally{runningAction.value=false}}
async function saveParameter(){try{const {value}=await ElMessageBox.prompt('保存这次计算的产流、汇流参数及配套起算规则','另存参数',{inputValue:selected.value.name,inputValidator:value=>Boolean(value?.trim())&&value.trim().length<=80});await modelApi('parameter-schemes',{method:'POST',body:{name:value.trim(),sourceTaskId:selectedId.value}});actionMessage.value='参数已保存，可在洪水模拟中选用。'}catch(failure){if(failure instanceof Error)error.value=failure.message}}
function openConditions(){const request=result.value?.frozenRequest||status.value?.runConfig?.request||status.value?.runConfig;const task=result.value?.primaryTaskId||result.value?.taskId||selectedId.value;if(request?.runType==='calibration')router.push({path:'/calibration',query:{taskId:task,schemeId:request.scheme?.id}});else router.push({path:'/simulation',query:selectedId.value.startsWith('OP-')?{operation:selectedId.value}:{task:task}})}
async function saveAsScheme(){try{const request=await modelApi('results/'+selectedId.value+'/scheme-conditions');const {value}=await ElMessageBox.prompt('将这次完整计算条件另存为方案，初次打开采用人工试调，之后可设置搜索参数。','另存为方案',{inputValue:selected.value.name,inputValidator:value=>Boolean(value?.trim())&&value.trim().length<=80});const method='reuse';const saved=await modelApi('model-schemes',{method:'POST',body:{name:value.trim(),definition:schemeDefinition(request,method),calculationDraft:request,editor:{editorTrialMode:request.calibration?.evaluationMode==='manual'?'manual':'automatic'}}});actionMessage.value='方案已保存，可在参数率定中打开。';return saved}catch(failure){if(failure instanceof Error)error.value=failure.message}}
watch(()=>[app.contextKey,route.query.result,route.query.operation,route.query.task],refresh,{immediate:true})
onBeforeUnmount(()=>{disposed=true;sequence++;clearTimeout(poll)})
</script>
<style scoped>
.results-workspace{display:grid;gap:18px;color:#30534c}.results-workspace>header{display:flex;align-items:center;justify-content:space-between}.results-workspace h1{font-size:26px;margin:6px 0}.eyebrow{font-size:14px;color:#6d8c81}.results-tools{display:flex;align-items:center;gap:14px}.result-tabs{display:flex;gap:6px}.results-tools>input{margin-left:auto;max-width:360px}.results-tools>select{width:160px}.results-layout{display:grid;grid-template-columns:minmax(280px,360px) minmax(0,1fr);gap:18px;align-items:start}.results-list{overflow:hidden}.list-count{padding:14px 18px;color:#71877e;font-size:14px;border-bottom:1px solid #dfe9e4}.result-row{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;padding:18px;border:0;border-bottom:1px solid #e4ebe7;background:#fff;text-align:left;color:#355b50;cursor:pointer}.result-row.selected{background:#eaf4f1;box-shadow:inset 3px 0 #277f80}.result-row div{display:grid;gap:8px}.result-row b{font-size:16px}.result-row span{font-size:14px;color:#73877d}.result-row i{font-style:normal}.results-list footer{display:flex;align-items:center;gap:5px;padding:14px;font-size:14px}.results-list footer>span{margin-right:auto}.result-detail{display:grid;gap:14px;min-width:0}.detail-heading{padding:20px}.detail-heading h2{font-size:21px;margin:0}.detail-heading p{font-size:14px;color:#71877d}.detail-actions{display:flex;gap:8px;flex-wrap:wrap}.result-placeholder,.empty{padding:40px 24px;text-align:center;color:#789085;font-size:14px}.timing-details{padding:18px;font-size:14px}.error{color:#a24737!important}.results-workspace :deep(.btn),.results-workspace .input{min-height:36px;font-size:14px}@media(max-width:1400px){.results-layout{grid-template-columns:290px minmax(0,1fr)}.results-tools{flex-wrap:wrap}}@media(max-width:1000px){.results-layout{grid-template-columns:1fr}.results-list{max-height:380px;overflow:auto}}
</style>
